     *
     * @return the next int read from the target stream
     * @throws IOException upon error
     */
    private int readWithUpdate() throws IOException {
        final int target = in.read();
        atEos = target == EOF;
        if (!atEos) {
            atSlashCr = target == CR;
            atSlashLf = target == LF;
        }
        return target;
    }
}

