    public static String separatorsToUnix(final String path) {
        if (path == null || path.indexOf(WINDOWS_NAME_SEPARATOR) == NOT_FOUND) {
            return path;
        }
        return path.replace(WINDOWS_NAME_SEPARATOR, UNIX_NAME_SEPARATOR);
    }

