public class FileUtils {
	private static final String CVS_FOLDER = "CVS";

	public static List<File> listFiles(File directory, IOFileFilter fileFilter, IOFileFilter dirFilter) {
		List<File> files = new ArrayList<>();
		for (File file : directory.listFiles()) {
			if (fileFilter == null || fileFilter.accept(file)) {
				files.add(file);
			}
			if (dirFilter == null || dirFilter.accept(file)) {
				if (file.isDirectory()) {
					files.addAll(listFiles(file, fileFilter, dirFilter));
				}
			}
		}
		return files;
	}

	public static List<File> listFiles(File directory) {
		return listFiles(directory, null, null);
	}

	public static List<File> listFiles(File directory, IOFileFilter fileFilter) {
		return listFiles(directory, fileFilter, null);
	}

	public static boolean deleteQuietly(File file) {
		if (file == null) {
			return false;
		}
		try {
			if (file.isDirectory()) {
				for (File child : file.listFiles()) {
					deleteQuietly(child);
				}
			}
			return file.delete();
		} catch (Exception e) {
			return false;
		}
	}

	public static boolean moveFile(File source, File destination) throws IOException {
		if (!source.exists()) {
			throw new FileNotFoundException("Source file does not exist: " + source);
		}
		if (destination.exists() && !destination.delete()) {
			throw new IOException("Failed to delete destination file: " + destination);
		}
		if (!renameTo(source, destination)) {
			copyFile(source, destination);
			return deleteQuietly(source);
		}
		return true;
	}

	public static boolean renameTo(File source, File destination) {
		if (!source.exists()) {
			throw new IllegalArgumentException("Source file does not exist: " + source);
		}
		if (destination.exists() && !destination.delete()) {
			throw new IllegalArgumentException("Failed to delete destination file: " + destination);
		}
		return source.renameTo(destination);
	}

	public static void copyFile(File source, File destination) throws IOException {
		if (!source.exists()) {
			throw new FileNotFoundException("Source file does not exist: " + source);
		}
		if (destination.exists() && !destination.delete()) {
			throw new IOException("Failed to delete destination file: " + destination);
		}
		try (InputStream in = new FileInputStream(source)) {
			try (OutputStream out = new FileOutputStream(destination)) {
				byte[] buffer = new byte[1024];
				int length;
				while ((length = in.read(buffer)) > 0) {
					out.write(buffer, 0, length);
				}
			}
		}
	}

	public static void copyDirectory(File sourceDir, File destinationDir) throws IOException {
		if (!sourceDir.exists()) {
			throw new FileNotFoundException("Source directory does not exist: " + sourceDir);
		}
		if (destinationDir.exists() && !destinationDir.isDirectory()) {
			throw new IOException("Destination is not a directory: " + destinationDir);
		}
		if (!destinationDir.exists() && !destinationDir.mkdirs()) {
			throw new IOException("Failed to create directory: " + destinationDir);
		}
		for (File file : sourceDir.listFiles()) {
			File destinationFile = new File(destinationDir, file.getName());
			if (file.isDirectory()) {
				copyDirectory(file, destinationFile);
			} else {
				copyFile(file, destinationFile);
			}
		}
	}

	public static boolean createParentDirectories(File file) throws IOException {
		if (file == null) {
			throw new NullPointerException("File must not be null");
		}
		File parent = file.getCanonicalFile().getParentFile();
		if (parent != null && !parent.exists() && !parent.mkdirs()) {
			throw new IOException("Failed to create parent directories of " + file);
		}
		return parent != null && parent.exists();
	}

	public static boolean isSameFile(File file1, File file2) throws IOException {
		if (file1 == null || file2 == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!file1.exists() || !file2.exists()) {
			return false;
		}
		File canonicalFile1 = file1.getCanonicalFile();
		File canonicalFile2 = file2.getCanonicalFile();
		return canonicalFile1.equals(canonicalFile2);
	}

	public static boolean isSameOrSubdirectory(File sub, File dir) throws IOException {
		if (sub == null || dir == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!dir.exists()) {
			return false;
		}
		File canonicalDir = dir.getCanonicalFile();
		File canonicalSub = sub.getCanonicalFile();
		while (canonicalSub != null) {
			if (canonicalSub.equals(canonicalDir)) {
				return true;
			}
			canonicalSub = canonicalSub.getParentFile();
		}
		return false;
	}

	public static boolean isNewer(File file1, File file2) throws IOException {
		if (file1 == null || file2 == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!file1.exists() || !file2.exists()) {
			return false;
		}
		long time1 = file1.lastModified();
		long time2 = file2.lastModified();
		return time1 > time2;
	}

	public static boolean isOlder(File file1, File file2) throws IOException {
		if (file1 == null || file2 == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!file1.exists() || !file2.exists()) {
			return false;
		}
		long time1 = file1.lastModified();
		long time2 = file2.lastModified();
		return time1 < time2;
	}

	public static boolean isFileNewer(File file, File reference) throws IOException {
		if (file == null || reference == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!file.exists() || !reference.exists()) {
			return false;
		}
		long time1 = file.lastModified();
		long time2 = reference.lastModified();
		return time1 > time2;
	}

	public static boolean isFileOlder(File file, File reference) throws IOException {
		if (file == null || reference == null) {
			throw new NullPointerException("Arguments must not be null");
		}
		if (!file.exists() || !reference.exists()) {
			return false;
