     * @throws IllegalArgumentException if the file does not exist.
     *
     * @since 2.0
     */
    public static long sizeOf(final File file) {
        requireExists(file, "file");
        if (file.isDirectory()) {
            return sizeOfDirectory0(file); // private method; expects directory
        }
        return file.length();
    }

    /**
